1	/**
2	 * node-dns.ts — stub shim for node:dns and node:dns/promises.
3	 *
4	 * CF Workers has no DNS resolution API; the only code that hits this in the
5	 * server package is the invite test-resolution handler, which is intentionally
6	 * not ported to the CF deployment. All other route handlers in access.ts can
7	 * be safely imported without triggering these stubs.
8	 */
9	
10	const notAvailable = (): Promise<never> =>
11	  Promise.reject(
12	    Object.assign(new Error("node:dns not available in Cloudflare Workers"), { code: "ENOTAVAIL" }),
13	  );
14	
15	export const lookup = notAvailable;
16	export const resolve = notAvailable;
17	export const resolve4 = notAvailable;
18	export const resolve6 = notAvailable;
19	
20	export const promises = { lookup };
21	
22	export default { lookup, resolve, resolve4, resolve6, promises };
